"""Straightforward (slow) reference model written directly from the contract text."""
import copy

MAXOFF = 4611686018427387903

ALLOWED = {
    'PADDING': 'IHZA', 'PING': 'IHZA', 'ACK': 'IHA', 'CRYPTO': 'IHA',
    'STREAM': 'ZA', 'RESET_STREAM': 'ZA', 'STOP_SENDING': 'ZA',
    'HANDSHAKE_DONE': '',
}

def run_trace(tid, cfg, events):
    keys = {'I': 'live', 'H': 'absent', 'Z': 'live' if cfg['early'] else 'absent', 'A': 'absent'}
    pnsets = {'I': set(), 'H': set(), 'APP': set()}
    streams = {}          # sid -> dict(data=dict, highest, final_size, reset, stopped, delivered=bytes)
    crypto = {'I': {'data': {}, 'highest': 0}, 'H': {'data': {}, 'highest': 0}, 'A': {'data': {}, 'highest': 0}}
    total = 0
    pending = []          # list of dicts
    last_act = 0
    records = {}          # (ev,pk) -> record
    conn = {'state': 'open', 'code': None, 'at_ms': None, 'source': None, 'peer_code': None}

    def space(level):
        return 'APP' if level in ('Z', 'A') else level

    def put(ev, pk, status, reason, at, frame=None):
        records[(ev, pk)] = {'event': ev, 'packet': pk, 'status': status, 'reason': reason,
                             'at_ms': at, 'frame': frame}

    def drop_pending(at, reason):
        for q in list(pending):
            put(q['ev'], q['pk'], 'dropped', reason, at)
        del pending[:]

    def terminate(state, code, at, ev, pk, frame, peer):
        if conn['state'] != 'open':
            return
        conn.update({'state': state, 'code': code, 'at_ms': at,
                     'source': {'event': ev, 'packet': pk, 'frame': frame}, 'peer_code': peer})
        drop_pending(at, 'CONNECTION_CLOSED')

    def prefix(data):
        n = 0
        while n in data:
            n += 1
        return bytes(data[i] for i in range(n))

    def merge_data(dst, off, b, reject):
        """returns False on rejected conflict"""
        for i in range(len(b)):
            o = off + i
            if o in dst and dst[o] != b[i] and reject:
                return False
        for i in range(len(b)):
            o = off + i
            if o not in dst:
                dst[o] = b[i]
        return True

    def get_stream(sid):
        if sid not in streams:
            streams[sid] = {'data': {}, 'highest': 0, 'final_size': None,
                            'reset': False, 'stopped': False, 'delivered': b''}
        return streams[sid]

    def do_frame(level, f, sid_state):
        global total
        t = f['type']
        if t == 'PADDING' or t == 'PING':
            return None
        if t == 'CRYPTO':
            end = f['offset'] + len(f['data'])
            if end > MAXOFF:
                return 'FRAME_ENCODING_ERROR'
            if end > cfg['crypto_limit']:
                return 'CRYPTO_BUFFER_EXCEEDED'
            cs = crypto[level]
            if not merge_data(cs['data'], f['offset'], f['data'], cfg['overlap'] == 'reject'):
                return 'PROTOCOL_VIOLATION'
            cs['highest'] = max(cs['highest'], end)
            return None
        if t == 'ACK':
            rs = f['ranges']
            if len(rs) == 0:
                return 'FRAME_ENCODING_ERROR'
            prev = None
            for lo, hi in rs:
                if lo > hi:
                    return 'FRAME_ENCODING_ERROR'
                if prev is not None and lo <= prev + 1:
                    return 'FRAME_ENCODING_ERROR'
                prev = hi
            sent = cfg['sent'][level]
            for lo, hi in rs:
                cur = lo
                while cur <= hi:
                    found = False
                    for slo, shi in sent:
                        if slo <= cur <= shi:
                            cur = shi + 1
                            found = True
                            break
                    if not found:
                        return 'PROTOCOL_VIOLATION'
            return None
        if t in ('STREAM', 'RESET_STREAM', 'STOP_SENDING'):
            sid = f['id']
            if t == 'STOP_SENDING':
                if sid % 4 != 0:
                    return 'STREAM_STATE_ERROR'
                if sid // 4 + 1 > cfg['max_streams_bidi']:
                    return 'STREAM_LIMIT_ERROR'
                get_stream(sid)['stopped'] = True
                return None
            if sid % 4 not in (0, 2):
                return 'STREAM_STATE_ERROR'
            lim = cfg['max_streams_bidi'] if sid % 4 == 0 else cfg['max_streams_uni']
            if sid // 4 + 1 > lim:
                return 'STREAM_LIMIT_ERROR'
            st = get_stream(sid)
            if t == 'RESET_STREAM':
                fsz = f['final_size']
                if st['final_size'] is not None and fsz != st['final_size']:
                    return 'FINAL_SIZE_ERROR'
                if fsz < st['highest']:
                    return 'FINAL_SIZE_ERROR'
                if fsz > cfg['max_stream_data']:
                    return 'FLOW_CONTROL_ERROR'
                nh = max(st['highest'], fsz)
                if total - st['highest'] + nh > cfg['max_data']:
                    return 'FLOW_CONTROL_ERROR'
                total += nh - st['highest']
                st['highest'] = nh
                st['final_size'] = fsz
                st['reset'] = True
                return None
            # STREAM
            off = f['offset']; b = f['data']; fin = f['fin']
            end = off + len(b)
            if end > MAXOFF:
                return 'FRAME_ENCODING_ERROR'
            if st['final_size'] is not None:
                if end > st['final_size'] or (fin and end != st['final_size']):
                    return 'FINAL_SIZE_ERROR'
            if fin and end < st['highest']:
                return 'FINAL_SIZE_ERROR'
            if end > cfg['max_stream_data']:
                return 'FLOW_CONTROL_ERROR'
            nh = max(st['highest'], end)
            if total - st['highest'] + nh > cfg['max_data']:
                return 'FLOW_CONTROL_ERROR'
            if not st['reset']:
                if not merge_data(st['data'], off, b, cfg['overlap'] == 'reject'):
                    return 'PROTOCOL_VIOLATION'
            total += nh - st['highest']
            st['highest'] = nh
            if fin:
                st['final_size'] = end
            if not st['reset']:
                st['delivered'] = prefix(st['data'])
            return None
        raise AssertionError(t)

    def process(ev, pk, p, at):
        global total
        level = p['level']
        if conn['state'] != 'open':
            put(ev, pk, 'dropped', 'CONNECTION_CLOSED', at)
            return
        if not p['auth']:
            put(ev, pk, 'dropped', 'AUTH', at)
            return
        if p['pn'] in pnsets[space(level)]:
            put(ev, pk, 'duplicate', 'DUPLICATE', at)
            return
        frames = p['frames']
        if len(frames) == 0:
            put(ev, pk, 'error', 'FRAME_ENCODING_ERROR', at, None)
            terminate('closed', 'FRAME_ENCODING_ERROR', at, ev, pk, None, None)
            return
        for i, f in enumerate(frames):
            if f['type'] == 'UNKNOWN':
                put(ev, pk, 'error', 'FRAME_ENCODING_ERROR', at, i)
                terminate('closed', 'FRAME_ENCODING_ERROR', at, ev, pk, i, None)
                return
            if f['type'] == 'CLOSE':
                if f['app'] and level not in ('Z', 'A'):
                    put(ev, pk, 'error', 'PROTOCOL_VIOLATION', at, i)
                    terminate('closed', 'PROTOCOL_VIOLATION', at, ev, pk, i, None)
                    return
            elif f['type'] not in ALLOWED or level not in ALLOWED[f['type']]:
                put(ev, pk, 'error', 'PROTOCOL_VIOLATION', at, i)
                terminate('closed', 'PROTOCOL_VIOLATION', at, ev, pk, i, None)
                return
        snap = (copy.deepcopy(streams), copy.deepcopy(crypto), total)
        close = None
        for i, f in enumerate(frames):
            if f['type'] == 'CLOSE':
                close = (i, f)
                break
            err = do_frame(level, f, None)
            if err:
                streams.clear(); streams.update(copy.deepcopy(snap[0]))
                crypto.clear(); crypto.update(copy.deepcopy(snap[1]))
                total = snap[2]
                put(ev, pk, 'error', err, at, i)
                terminate('closed', err, at, ev, pk, i, None)
                return
        pnsets[space(level)].add(p['pn'])
        last_act_local = at
        put(ev, pk, 'accepted', 'OK', at, None)
        set_last(last_act_local)
        if close:
            i, f = close
            code = 'PEER_APPLICATION_CLOSE' if f['app'] else 'PEER_TRANSPORT_CLOSE'
            terminate('closed', code, at, ev, pk, i, f['code'])

    def set_last(v):
        nonlocal last_act
        last_act = v

    def drain(level, at):
        sel = [q for q in pending if q['level'] == level]
        for q in sel:
            pending.remove(q)
            if conn['state'] != 'open':
                put(q['ev'], q['pk'], 'dropped', 'CONNECTION_CLOSED', conn['at_ms'])
                continue
            process(q['ev'], q['pk'], q['p'], at)

    for ev, e in enumerate(events):
        t = e['t']
        if conn['state'] == 'open' and cfg['idle_ms'] > 0 and t >= last_act + cfg['idle_ms']:
            terminate('idle', 'IDLE_TIMEOUT', last_act + cfg['idle_ms'], ev, None, None, None)
        if conn['state'] != 'open':
            if e['op'] == 'datagram':
                for pk in range(len(e['packets'])):
                    put(ev, pk, 'dropped', 'CONNECTION_CLOSED', t)
            continue
        if e['op'] == 'key':
            lv = e['level']
            if e['action'] == 'discard':
                if keys[lv] != 'discarded':
                    keys[lv] = 'discarded'
                    for q in [q for q in pending if q['level'] == lv]:
                        put(q['ev'], q['pk'], 'dropped', 'KEYS_DISCARDED', t)
                        pending.remove(q)
            else:
                if keys[lv] == 'absent':
                    keys[lv] = 'live'
                    drain(lv, t)
        elif e['op'] == 'tick':
            pass
        else:
            size = e['bytes']
            pkts = e['packets']
            if any(p['level'] == 'A' for p in pkts[:-1]):
                for pk in range(len(pkts)):
                    put(ev, pk, 'dropped', 'LAYOUT', t)
                continue
            for pk, p in enumerate(pkts):
                lv = p['level']
                if conn['state'] != 'open':
                    put(ev, pk, 'dropped', 'CONNECTION_CLOSED', t)
                    continue
                if lv == 'I' and size < 1200:
                    put(ev, pk, 'dropped', 'INITIAL_TOO_SMALL', t)
                    continue
                if lv == 'Z' and not cfg['early']:
                    put(ev, pk, 'dropped', 'EARLY_REJECTED', t)
                    continue
                if keys[lv] == 'discarded':
                    put(ev, pk, 'dropped', 'KEYS_DISCARDED', t)
                    continue
                if keys[lv] == 'absent':
                    if len(pending) < cfg['buffer_packets']:
                        pending.append({'ev': ev, 'pk': pk, 'level': lv, 'p': p, 't': t})
                    else:
                        put(ev, pk, 'dropped', 'BUFFER_FULL', t)
                    continue
                process(ev, pk, p, t)
    for q in pending:
        put(q['ev'], q['pk'], 'buffered', 'NO_KEYS', q['t'])
    order = sorted(records.keys())
    packets = [records[k] for k in order]
    c = dict(conn)
    c['last_activity_ms'] = last_act
    out_streams = []
    for sid in sorted(streams):
        st = streams[sid]
        out_streams.append({'id': sid, 'highest': st['highest'], 'final_size': st['final_size'],
                            'reset': st['reset'], 'stopped': st['stopped'],
                            'delivered_hex': st['delivered'].hex()})
    out_crypto = []
    for lv in ('I', 'H', 'A'):
        cs = crypto[lv]
        out_crypto.append({'level': lv, 'highest': cs['highest'], 'contiguous_hex': prefix(cs['data']).hex()})
    return {'id': tid, 'packets': packets, 'connection': c,
            'keys': {k: keys[k] for k in 'IHZA'}, 'received_total': total,
            'streams': out_streams, 'crypto': out_crypto}
PYEOF
